import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import type {
  ContentViewConfig,
  CornerViewConfig,
  RootViewConfig,
  ScrollbarViewConfig,
  ThumbViewConfig,
  ViewConfig,
  ViewportViewConfig,
} from "../../../base-ui/ui/scroll-area";
import {
  shadcnScrollAreaContentClasses,
  shadcnScrollAreaCornerClasses,
  shadcnScrollAreaFadeClasses,
  shadcnScrollAreaRootClasses,
  shadcnScrollAreaScrollbarClasses,
  shadcnScrollAreaThumbClasses,
  shadcnScrollAreaViewportClasses,
} from "./view";

export type {
  ContentViewConfig,
  CornerViewConfig,
  RootViewConfig,
  ScrollAreaStyle,
  ScrollbarViewConfig,
  ThumbViewConfig,
  ViewConfig,
  ViewportViewConfig,
} from "../../../base-ui/ui/scroll-area";

export {
  shadcnScrollAreaContentClasses,
  shadcnScrollAreaCornerClasses,
  shadcnScrollAreaFadeClasses,
  shadcnScrollAreaRootClasses,
  shadcnScrollAreaScrollbarClasses,
  shadcnScrollAreaThumbClasses,
  shadcnScrollAreaViewportClasses,
} from "./view";

const cn = (base: string, classes?: string): string =>
  [base, classes]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

const stateAttributes = <ParentMessage>(
  h: ReturnType<typeof html<ParentMessage>>,
  config: Pick<RootViewConfig, "hasOverflowX" | "hasOverflowY" | "isScrolling">
) => [
  ...(config.hasOverflowX === true
    ? [h.DataAttribute("has-overflow-x", "")]
    : []),
  ...(config.hasOverflowY === true
    ? [h.DataAttribute("has-overflow-y", "")]
    : []),
  ...(config.isScrolling === true ? [h.DataAttribute("scrolling", "")] : []),
];

export const rootView = <ParentMessage>({
  children,
  classes,
  style,
  hasOverflowX,
  hasOverflowY,
  isScrolling,
}: RootViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...stateAttributes(h, { hasOverflowX, hasOverflowY, isScrolling }),
      h.DataAttribute("slot", "scroll-area"),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(shadcnScrollAreaRootClasses, classes)),
    ],
    children
  );
};

export const viewportView = <ParentMessage>({
  children,
  classes,
  style,
  ariaLabel,
}: ViewportViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("tabindex", "0"),
      h.DataAttribute("slot", "scroll-area-viewport"),
      ...(ariaLabel === undefined
        ? []
        : [h.Attribute("role", "region"), h.AriaLabel(ariaLabel)]),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(shadcnScrollAreaViewportClasses, classes)),
    ],
    children
  );
};

export const contentView = <ParentMessage>({
  children,
  classes,
  style,
}: ContentViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(shadcnScrollAreaContentClasses, classes)),
    ],
    children
  );
};

export const scrollbarView = <ParentMessage>({
  children,
  orientation = "vertical",
  classes,
  style,
}: ScrollbarViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.AriaHidden(true),
      h.DataAttribute("slot", "scroll-area-scrollbar"),
      h.DataAttribute("orientation", orientation),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(shadcnScrollAreaScrollbarClasses, classes)),
    ],
    children
  );
};

export const thumbView = <ParentMessage>({
  classes,
  style,
}: ThumbViewConfig = {}): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...(style === undefined ? [] : [h.Style(style)]),
      h.DataAttribute("slot", "scroll-area-thumb"),
      h.Class(cn(shadcnScrollAreaThumbClasses, classes)),
    ],
    []
  );
};

export const cornerView = <ParentMessage>({
  classes,
  style,
}: CornerViewConfig = {}): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.AriaHidden(true),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(shadcnScrollAreaCornerClasses, classes)),
    ],
    []
  );
};

export const view = <ParentMessage>({
  children,
  ariaLabel,
  hasFade = false,
  classes,
  style,
  viewportClasses,
  viewportStyle,
  contentClasses,
  contentStyle,
  hasHorizontalScrollbar = false,
}: ViewConfig): Html =>
  rootView<ParentMessage>({
    classes,
    style,
    hasOverflowY: true,
    hasOverflowX: hasHorizontalScrollbar,
    children: [
      viewportView<ParentMessage>({
        ariaLabel,
        classes: hasFade
          ? cn(shadcnScrollAreaFadeClasses, viewportClasses)
          : viewportClasses,
        style: viewportStyle,
        children: [
          contentView<ParentMessage>({
            classes: contentClasses,
            style: contentStyle,
            children,
          }),
        ],
      }),
      scrollbarView<ParentMessage>({
        children: [thumbView<ParentMessage>()],
      }),
      ...(hasHorizontalScrollbar
        ? [
            scrollbarView<ParentMessage>({
              orientation: "horizontal",
              classes: "inset-x-0 bottom-0 h-2.5 w-full border-l-0 border-t border-t-transparent",
              children: [thumbView<ParentMessage>()],
            }),
          ]
        : []),
    ],
  });

export const shadcnScrollAreaRootClasses =
  "relative overflow-hidden";
export const shadcnScrollAreaViewportClasses =
  "h-full w-full rounded-[inherit] overflow-auto overscroll-contain transition-[color,box-shadow] outline-none focus-visible:ring-[3px] focus-visible:ring-gray-950/10 focus-visible:outline-1 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden";
export const shadcnScrollAreaContentClasses =
  "min-w-0";
export const shadcnScrollAreaScrollbarClasses =
  "absolute inset-y-0 right-0 flex touch-none select-none p-px transition-colors h-full w-2.5 border-l border-l-transparent";
export const shadcnScrollAreaThumbClasses =
  "relative flex-1 rounded-full bg-gray-200";
export const shadcnScrollAreaCornerClasses =
  "pointer-events-none absolute bottom-0 right-0 h-2.5 w-2.5 bg-white";
export const shadcnScrollAreaFadeClasses =
  "[mask-image:linear-gradient(to_bottom,transparent,black_1rem,black_calc(100%-1rem),transparent)]";

import { describe, expect, test } from "vitest";

import { scrollAreaScrollbarClasses } from "../../../base-ui/ui/scroll-area";
import * as ScrollArea from "./index";

describe("shadcn Scroll Area registry view", () => {
  test("exports the Foldkit Scroll Area view contract", () => {
    expect(ScrollArea.rootView).toBeTypeOf("function");
    expect(ScrollArea.viewportView).toBeTypeOf("function");
    expect(ScrollArea.view).toBeTypeOf("function");
    expect(ScrollArea.shadcnScrollAreaRootClasses).toBe(
      "relative overflow-hidden"
    );
  });

  test("uses shadcn indicator styling instead of the base scrollbar lane", () => {
    expect(ScrollArea.shadcnScrollAreaViewportClasses).toContain(
      "[scrollbar-width:none]"
    );
    expect(ScrollArea.shadcnScrollAreaViewportClasses).toContain(
      "focus-visible:ring-[3px]"
    );
    expect(ScrollArea.shadcnScrollAreaScrollbarClasses).toContain(
      "flex touch-none select-none p-px transition-colors"
    );
    expect(ScrollArea.shadcnScrollAreaScrollbarClasses).toContain(
      "h-full w-2.5 border-l border-l-transparent"
    );
    expect(ScrollArea.shadcnScrollAreaThumbClasses).toContain("flex-1");
    expect(ScrollArea.shadcnScrollAreaThumbClasses).toContain("bg-gray-200");
    expect(ScrollArea.shadcnScrollAreaScrollbarClasses).not.toEqual(
      scrollAreaScrollbarClasses
    );
  });
});
